// hy — Հայերեն (armênio).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// POR QUE ENTROU: é a língua do Estado na ARMÊNIA (Constituição, art. 20), e a Armênia era um dos quatro
// membros da ONU que nenhuma língua do Syden alcançava.
//
// CONFIANÇA: MÉDIA, e o arquivo diz isso para quem vier depois. Antes de escrever houve PESQUISA, em
// 04/10/2026: o vocabulário de base veio da tradução do MediaWiki para o armênio (languages/i18n/hy.json —
// Մտնել, Ելնել, Որոնել, Խմբագրել, Չեղարկել, Թաքցնել, Ներբեռնել, Հաստատել), das extensões Echo
// (Ծանուցումներ) e DiscussionTools (Պատասխան, Բաժանորդագրվել), do aplicativo móvel da Wikipédia
// (Կարգավորումներ, Պահպանել) e do GNOME (Պատճենել, Աղբարկղ, Տառատեսակ, Վերանվանել). A tradução do GNOME
// em armênio é antiga e tem erros (Disconnect = "Միանալ"), por isso só valeu o que bate com uma segunda
// fonte. O resto é escolha minha, e quem ler armênio troca numa linha.
//
// TOM: **դու**, e não *Դուք* (CLAUDE.md, "Os idiomas tratam por você"). Os BOTÕES vão no infinitivo
// ("Պահպանել", "Ջնջել"), como no MediaWiki e em toda interface armênia: o infinitivo não trata ninguém.
// As frases conjugam na segunda pessoa do singular ("քո", "Ընտրիր").
//
// GÊNERO: NÃO HÁ. O armênio não tem gênero gramatical: *նա* é "ele" e "ela", e nenhum verbo ou adjetivo
// muda com o sexo de quem lê ou de quem fala. É a primeira língua das quatro desta leva em que a releitura
// de gênero não acha nada para achar.
//
// PONTUAÇÃO ARMÊNIA, que é o que mais engana quem não lê: o PONTO FINAL é **։** (U+0589), que parece
// dois-pontos; a INTERROGAÇÃO é **՞**, posta EM CIMA da vogal tônica da palavra perguntada, e não no fim
// ("Մոռացե՞լ ես"); a vírgula de pausa é **՝**; e o que em português seria dois-pontos no meio da frase
// é **․** (U+2024, *mijaket*), menos na abreviação "էլ. փոստ", que leva o ponto latino. Nos rótulos, os
// dois-pontos são os latinos.
//
// PLURAL: depois de número, o substantivo fica no SINGULAR ("5 հաղորդագրություն", "15 անդամ") — certo
// para qualquer n.
//
// CASOS E {CAMPOS}: o armênio cola o caso no fim da palavra ("համայնքում", "Syden-ին"). Um {campo} não
// recebe sufixo: o caso vai num substantivo ao lado ("{comunidade} համայնքում") ou o {campo} vem depois
// de ՝.
//
// NÚMEROS: o Chrome não tem dados do armênio; `algarismos.ts` já cai na separação neutra, com 0-9, que é
// o que o armênio usa.
//
// FRASES PARTIDAS: algumas chaves são pedaços de uma frase com uma palavra em código no meio (".lrc",
// ".txt", o nome da comunidade). A ordem armênia não é a portuguesa, então cada pedaço foi escrito para
// fechar sozinho, e não como tradução palavra a palavra do pedaço.
//
// VOCABULÁRIO, decidido uma vez: comunidade = համայնք, canal = ալիք, sala de voz = ձայնային սենյակ,
// chamada = զանգ, conversa = զրույց, mensagem = հաղորդագրություն, senha = գաղտնաբառ, lixeira =
// աղբարկղ, tópico = ճյուղ (para não brigar com *թեմա*, que é o tema claro/escuro), conta = հաշիվ,
// administrador = ադմինիստրատոր, dono = սեփականատեր, cargo = դեր, convite = հրավեր, perfil = պրոֆիլ,
// transmissão = հեռարձակում, tela = էկրան, membro = անդամ, pacote = փաթեթ, enquete = հարցում, denúncia
// = բողոք, notificação = ծանուցում, vila = գյուղ, guarda-roupa = զգեստապահարան, cutucada = հրում, recado
// da tela de boas-vindas = ուղերձ, colar = զետեղել (porque *տեղադրել* é instalar).
//
// VOZ E SOM SEPARADOS: voz = ձայն (a da pessoa, a da chamada); som de soundboard e de aviso = հնչյուն.
// SELO E INSÍGNIA SEPARADOS: selo = կնիք (o da comunidade), insígnia = կրծքանշան (a da pessoa).

