  'Clique no ícone à esquerda do endereço do site, ative o Microfone, e o Syden liga sozinho.':
    'Սեղմիր կայքի հասցեի ձախ կողմի պատկերակին, միացրու Խոսափողը, և Syden-ն ինքը կմիանա։',
  'Clique para escolher quais aparecem no seu perfil (até {limite}).': 'Սեղմիր՝ ընտրելու, թե որոնք երևան քո պրոֆիլում (մինչև {limite})։',
