  'Comunidades': 'Համայնքներ',
  'Confete, fogos e corações que qualquer pessoa da sala pode mandar. Desligue se o seu computador engasgar durante a chamada — desligado, você não vê nem manda.':
    'Կոնֆետի, հրավառություն և սրտիկներ, որ սենյակում ցանկացածը կարող է ուղարկել։ Անջատիր, եթե համակարգիչդ դանդաղում է զանգի ժամանակ — անջատված վիճակում ոչ տեսնում ես, ոչ ուղարկում։',
  'Configurações': 'Կարգավորումներ',
