  'Criar uma conta': 'Ստեղծել հաշիվ',
  'De graça, para qualquer pessoa': 'Անվճար, ցանկացածի համար',
  'Definir a minha senha': 'Սահմանել իմ գաղտնաբառը',
  'Definir uma senha': 'Սահմանել գաղտնաբառ',
  'Deixar marcar mais de uma opção': 'Թույլ տալ նշել մեկից ավելի տարբերակ',
  'Deixe o título e o recado em branco para desmontar a tela: a comunidade volta a abrir direto nos canais.':
    'Վերնագիրն ու ուղերձը դատարկ թող՝ էկրանը հանելու համար․ համայնքը նորից կբացվի ուղիղ ալիքներով։',
  'Denúncia enviada': 'Բողոքն ուղարկվեց',
  'Denúncias': 'Բողոքներ',
  'Desativar áudio': 'Անջատել ձայնը',
  'Perfil': 'Պրոֆիլ',
  'Alterar apelido': 'Փոխել մականունը',
  'Apelido nesta comunidade': 'Մականուն այս համայնքում',
  'Vazio volta ao nome da conta': 'Դատարկը վերադառնում է հաշվի անվանը',
  'Nome de exibição': 'Ցուցադրվող անուն',
  'É o nome que todos veem no Syden. Para entrar e nas menções com @, continua valendo o nome da conta.': 'Սա այն անունն է, որը բոլորը տեսնում են Syden-ում։ Մուտքի և @-ով նշումների համար շարունակում է գործել հաշվի անունը։',
  'Cargo': 'Դեր',
  'Mover para': 'Տեղափոխել',
  'Desbloqueado': 'Արգելափակումը հանված է',
  'Desbloquear': 'Հանել արգելափակումը',
  'Descartar': 'Անտեսել',
  'Desconecta o Syden em todos os outros computadores e celulares. Você continua conectado aqui.':
    'Դուրս է հանում Syden-ը բոլոր մյուս համակարգիչներից և հեռախոսներից։ Այստեղ մնում ես միացված։',
  'Desconectando…': 'Անջատվում է…',
  'Desconectar': 'Անջատել',
  'Descrição': 'Նկարագրություն',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.':
    'Անջատված վիճակում սենյակում գտնվողի հեռարձակումը երևում է որպես հրավեր և սկսում է ներբեռնվել միայն այն ժամանակ, երբ սեղմում ես Դիտել։ Սա խնայում է ինտերնետն ու պրոցեսորը — հատկապես լեփ-լեցուն սենյակում։',
  'Desligar câmera': 'Անջատել տեսախցիկը',
  'Deste servidor': 'Այս համայնքից',
  'Diga o e-mail da sua conta e mandamos um link para escolher outra.':
    'Գրիր քո հաշվի էլ. փոստը, և կուղարկենք հղում՝ նորն ընտրելու համար։',
  'Digite sua senha para confirmar': 'Մուտքագրիր գաղտնաբառդ՝ հաստատելու համար',
  'Disponível': 'Հասանելի',
  'Do laranja ao vermelho, como carvão aceso.': 'Նարնջագույնից կարմիր, ինչպես վառվող ածուխ։',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'Երկու էմոջի՝ նույն անունով․ յուրաքանչյուրին իր անունն է պետք։',
  'Dono': 'Սեփականատեր',
  'Dono da comunidade': 'Համայնքի սեփականատեր',
  'Dourado com brilho que passa devagar.': 'Ոսկեգույն՝ դանդաղ անցնող փայլով։',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.':
    'Զանգի ժամանակ այդ կոճակը նվագում է այս հնչյունները սենյակում բոլորի համար։ Տեղադրիր պատրաստի փաթեթներ կամ վերբեռնիր քոնը․ քո սիրելին մնում է վահանակի առջևում։',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'Սա առաջին բանն է, որ մարդը տեսնում է համայնք մտնելիս, միայն մեկ անգամ։ Առանց դրա՝ նա հայտնվում է ուղիղ ալիքների ցանկում։',
  'É assim que os outros veem você na lista e nas conversas.': 'Այսպես են քեզ տեսնում մյուսները ցանկում և զրույցներում։',
  'é o que você está enviando': 'այն է, ինչ դու ուղարկում ես',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.':
    'Սա մուտքի քո միակ ճանապարհն է։ Սահմանիր գաղտնաբառ՝ անջատելուց առաջ։',
  'E-mail': 'Էլ․ փոստ',
  'Eco de lugar grande e vazio.': 'Մեծ ու դատարկ վայրի արձագանք։',
  'Efeito do nome': 'Անվան էֆեկտ',
  'Efeito para a sala': 'Էֆեկտ սենյակի համար',
  'Efeitos visuais na chamada': 'Տեսողական էֆեկտներ զանգում',
  'Em branco: fica até você apagar.': 'Դատարկ՝ մնում է, մինչև ջնջես։',
  'Em branco: já.': 'Դատարկ՝ անմիջապես։',
