  'Encerrar a apresentação': 'Ավարտել ներկայացումը',
  'Endereço': 'Հասցե',
  'Endereço guardado. Confira a sua caixa de entrada para confirmar.': 'Հասցեն պահպանվեց։ Ստուգիր մուտքի արկղդ՝ հաստատելու համար։',
  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.':
    'Հասցեն պահպանվեց։ Այս սերվերում էլ. նամակների ուղարկումը դեռ միացված չէ, ուստի հաստատման հղումը մնաց սերվերի գրանցամատյանում։',
  'Enfeites, sons e emojis': 'Զարդեր, հնչյուններ և էմոջիներ',
  'Enquanto isto aparecer, os números abaixo não existem —': 'Քանի դեռ սա երևում է, ներքևի թվերը գոյություն չունեն —',
