  'Online agora: {n}': 'Հիմա առցանց՝ {n}',
  'Os números aparecem no alto da lista de canais, para todo mundo, e mudam sozinhos.': 'Թվերը բոլորի համար երևում են ալիքների ցանկի վերևում և թարմանում են ինքնուրույն։',
  'Criar uma sala para cada pessoa que entrar': 'Ստեղծել սենյակ յուրաքանչյուր մտնողի համար',
  'Entre para criar a sua sala': 'Մտիր՝ քո սենյակը ստեղծելու համար',
  'Limite de pessoas': 'Մարդկանց սահմանաչափ',
  'Quantas pessoas cabem (0 = sem limite)': 'Քանի մարդ է տեղավորվում (0 = առանց սահմանի)',
  'Canal de destaques': 'Ընտրվածների ալիք',
  'Destaques': 'Ընտրվածներ',
  'Estrelas necessárias': 'Անհրաժեշտ աստղեր',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'Երբ հաղորդագրությունը հավաքում է բավարար ⭐ աստղ, Syden-ը այն հրապարակում է ընտրվածների ալիքում։ Գրողի սեփական աստղը չի հաշվվում, իսկ հաղորդագրությունը ջնջելիս ջնջվում է նաև ընտրվածը։',
  '🎉 Resultado do sorteio de {premio}: {vencedores}. Parabéns!': '🎉 {premio} վիճակահանության արդյունքը՝ {vencedores}։ Շնորհավո՛ր։',
  '🎉 Sorteio: {premio}! Reaja com 🎉 para participar. O resultado sai em {quando}.': '🎉 Վիճակահանություն՝ {premio}։ Մասնակցելու համար արձագանքիր 🎉-ով։ Արդյունքը՝ {quando}։',
  'Começar o sorteio': 'Սկսել վիճակահանությունը',
  'Encerrar agora': 'Ավարտել հիմա',
  'Ganhadores': 'Մրցանակների քանակ',
  'Ninguém participou.': 'Ոչ ոք չմասնակցեց։',
  'Novo sorteio': 'Նոր վիճակահանություն',
  'O sorteio de {premio} terminou sem participantes.': '{premio} վիճակահանությունն ավարտվեց առանց մասնակիցների։',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden-ը ալիքում հայտարարում է մրցանակը, և ով ուզում է մասնակցել, արձագանքում է 🎉-ով։ Նշված ժամին վիճակ է հանում արձագանքողների միջից և հրապարակում արդյունքը։',
  'Participantes: {n}': 'Մասնակիցներ՝ {n}',
  'Prêmio': 'Մրցանակ',
