  'Aniversário': 'Ծննդյան օր',
  'Aniversários': 'Ծննդյան օրեր',
  'Canal dos parabéns': 'Շնորհավորանքների ալիք',
  'Dia': 'Օր',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Այսօր {pessoa}-ի ծննդյան օրն է։ 🎉 Ծնունդդ շնորհավոր։',
  'Mês': 'Ամիս',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Ամսաթիվը նշածի ծննդյան օրը Syden-ը ընտրված ալիքում շնորհավորանք է հրապարակում։ Անվան փոխարեն օգտագործեք {pessoa}։',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Միայն օրն ու ամիսը, երբեք տարին։ Ծննդյան օրերը հայտարարող համայնքները շնորհավորում են հենց այդ օրը։ Պարտադիր չէ, և կարելի է ջնջել ցանկացած պահի։',
  'Texto dos parabéns': 'Շնորհավորանքի տեքստը',
