  'Mensagens agendadas': 'Պլանավորված հաղորդագրություններ',
  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'Նշանակված ժամին Syden-ը տեքստը հրապարակում է ալիքում։ Կարելի է կրկնել ամեն օր կամ ամեն շաբաթ։',
