  'Todo dia': 'Ամեն օր',
  'Uma vez': 'Մեկ անգամ',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'Ինչ-որ մեկը հաղորդագրության սկզբում գրում է հրաման, օրինակ՝ !regras, և Syden-ը ալիքում պատասխանում է ձեր մուտքագրած տեքստով։ Օգտագործեք {pessoa}՝ հարցնողի անվան համար, և {comunidade}՝ համայնքի անվան համար։',
