  'Você está em silêncio nesta comunidade até {hora}.': 'Այս համայնքում լռության մեջ եք մինչև {hora}։',
  'Você recebeu uma advertência em {comunidade}: {motivo}': '{comunidade}-ում զգուշացում եք ստացել՝ {motivo}',
  'Barrar excesso de mensagens (mais de 5 em 10 segundos)': 'Կանգնեցնել չափազանց շատ հաղորդագրությունները (10 վայրկյանում 5-ից ավելի)',
  'Bloquear links nas mensagens': 'Արգելափակել հղումները հաղորդագրություններում',
  'Desligado': 'Անջատված',
  'Modo lento': 'Դանդաղ ռեժիմ',
  'Modo lento de {canal}': '{canal}-ի դանդաղ ռեժիմ',
  'Modo lento: uma mensagem a cada {tempo}.': 'Դանդաղ ռեժիմ՝ մեկ հաղորդագրություն ամեն {tempo}։',
  'Palavras proibidas': 'Արգելված բառեր',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'Որքան է յուրաքանչյուրը սպասում հաղորդագրությունների միջև ալիքում։',
  'Regras': 'Կանոններ',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Կանոններ, որոնք Syden-ն ինքն է կիրառում՝ նախքան հաղորդագրության երևալը։ Ադմինիստրատորներին չեն վերաբերում։ Արգելափակված հաղորդագրությունը պատճառով հետ է գնում գրողին, և ուրիշ ոչ ոք այն չի տեսնում։',
  'Salvo.': 'Պահպանված է։',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'Մեկը յուրաքանչյուր տողում։ Հաշվվում է ամբողջ բառը՝ առանց շեշտի կամ մեծատառի տարբերության։ Բառն արգելելը չի արգելափակում ավելի երկար բառ, որը պարզապես պարունակում է այն։',
  '{faltam} pontos para o nível {proximo}.': '{faltam} միավոր մինչև {proximo} մակարդակ։',
  'Adicionar recompensa': 'Ավելացնել պարգև',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'Յուրաքանչյուր հաղորդագրություն միավոր է բերում (րոպեում մեկ), ինչպես և ուրիշի հետ սենյակում անցկացրած յուրաքանչյուր րոպե։ Ով բարձրանում է մակարդակով, ծանուցում է ստանում միայն իր համար։',
  'Cargo da recompensa': 'Պարգևի դերը',
