  'Mandamos um link para confirmar. É por ele que você recupera a senha, se um dia esquecer.':
    'Հաստատման հղում ուղարկեցինք։ Դրանով կվերականգնես գաղտնաբառը, եթե երբևէ մոռանաս։',
