  'Montar esta tela': 'Կառուցել այս էկրանը',
  'Abrir em janela flutuante': 'Բացել լողացող պատուհանում',
  'Mostrar quem está sem vídeo': 'Ցույց տալ առանց տեսանյութի մարդկանց',
  'Mostrar a minha própria câmera': 'Ցույց տալ իմ սեփական տեսախցիկը',
  'Muda como os outros ouvem você na chamada. Vale na hora, dá para trocar durante a conversa — e acaba quando você sai da sala: na próxima você entra com a sua voz.':
    'Փոխում է, թե ինչպես են մյուսները քեզ լսում զանգում։ Գործում է անմիջապես, կարող ես փոխել զրույցի ընթացքում — և ավարտվում է, երբ դուրս ես գալիս սենյակից․ հաջորդ անգամ կմտնես քո ձայնով։',
  'Mudar a largura de {barra}': 'Փոխել լայնությունը՝ {barra}',
  'Mudar esta tela': 'Փոխել այս էկրանը',
  'Muita gente procurando GIF agora. Tente de novo daqui a pouco.': 'Հիմա շատերն են GIF որոնում։ Փորձիր մի քիչ հետո։',
  'Nada digno de nota até agora.': 'Առայժմ ուշագրավ ոչինչ։',
  'Nada é baixado enquanto você não abrir': 'Ոչինչ չի ներբեռնվում, քանի դեռ չես բացել',
  'Nada faltando: o pacote está completo.': 'Ոչինչ չի պակասում․ փաթեթն ամբողջական է։',
  'Nada na lixeira.': 'Աղբարկղը դատարկ է։',
  'Nada registrado ainda. Só aparecem aqui as ações com poder sobre os outros.':
    'Դեռ ոչինչ գրանցված չէ։ Այստեղ երևում են միայն այն գործողությունները, որոնք իշխանություն ունեն ուրիշների վրա։',
  'Não achei o áudio dessa página. No MyInstants, copie o link do botão de baixar e cole aqui.':
    'Այդ էջում աուդիո չգտա։ MyInstants-ում պատճենիր ներբեռնման կոճակի հղումը և զետեղիր այստեղ։',
  'Não chegou? Veja também a caixa de spam.': 'Չի՞ հասել։ Նայիր նաև սպամի թղթապանակում։',
  'Não dá para desfazer.': 'Հնարավոր չէ հետարկել։',
  'Não deu para falar com o GIPHY agora.': 'Հիմա չհաջողվեց կապվել GIPHY-ի հետ։',
  'Não deu para fechar o clipe agora. Tente de novo em alguns segundos.': 'Հիմա չհաջողվեց փակել հոլովակը։ Փորձիր մի քանի վայրկյանից։',
  'Não deu para salvar o selo.': 'Չհաջողվեց պահպանել կնիքը։',
  'Não deu para tirar o selo.': 'Չհաջողվեց հանել կնիքը։',
  'Não deu para trazer o canal de volta.': 'Չհաջողվեց վերականգնել ալիքը։',
  'Não foi possível falar com o servidor.': 'Չհաջողվեց կապվել սերվերի հետ։',
  'Não há transmissão para clipar agora.': 'Հիմա կտրելու հեռարձակում չկա։',
  'Não para nunca': 'Երբեք չի կանգնում',
  'Não perturbe': 'Չանհանգստացնել',
  'Não se compra: conquista-se.': 'Չի գնվում՝ վաստակվում է։',
  'Nebulosa': 'Միգամածություն',
  'Nenhum GIF para essa busca.': 'Այս որոնմամբ GIF չկա։',
  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.':
    'Դեռ ոչ մի փաթեթ չկա։ Ստեղծիր առաջինը քո պատկերներով կամ հրապարակիր այն էմոջիները, որ այս համայնքն արդեն ունի։',
  'Nenhum som com esse nome.': 'Այդ անունով հնչյուն չկա։',
  'Nenhuma denúncia até agora.': 'Առայժմ ոչ մի բողոք չկա։',
  'Nenhuma música ainda. Suba um arquivo que você tenha aí para a turma cantar.':
    'Դեռ ոչ մի երգ չկա։ Վերբեռնիր քո ունեցած ֆայլը, որ բոլորը երգեն։',
  'Ninguém abriu a sua transmissão ainda. O Syden só codifica a imagem quando alguém assiste — por isso não há números aqui.':
    'Քո հեռարձակումը դեռ ոչ ոք չի բացել։ Syden-ը պատկերը կոդավորում է միայն այն ժամանակ, երբ ինչ-որ մեկը դիտում է — դրա համար այստեղ թվեր չկան։',
  'Ninguém com a palavra ainda': 'Դեռ ոչ ոքի խոսք չի տրված',
  'Ninguém é avisado de que foi bloqueado.': 'Ոչ ոքի չեն տեղեկացնում, որ արգելափակվել է։',
  'Ninguém entrou em chamada este mês ainda.': 'Այս ամիս դեռ ոչ ոք զանգի չի միացել։',
  'Ninguém mais nesta comunidade ainda.': 'Այս համայնքում դեռ ուրիշ ոչ ոք չկա։',
  'Ninguém na chamada — seja o primeiro': 'Զանգում ոչ ոք չկա — եղիր առաջինը',
  'Ninguém para sugerir por enquanto — entre numa comunidade para conhecer gente.':
    'Առայժմ առաջարկելու ոչ ոք չկա — մտիր որևէ համայնք՝ մարդկանց ճանաչելու համար։',
  'Ninguém respondeu neste tópico ainda.': 'Այս ճյուղում դեռ ոչ ոք չի պատասխանել։',
  'Noite estrelada': 'Աստղազարդ գիշեր',
  'Nome': 'Անուն',
  'Nome alterado.': 'Անունը փոխվեց։',
  'Nome da comunidade': 'Համայնքի անուն',
  'Nome de usuário': 'Օգտանուն',
  'Nome do grupo (opcional)': 'Խմբի անուն (ըստ ցանկության)',
