  'Nova conversa': 'Նոր զրույց',
  'Nova conversa em grupo': 'Նոր խմբային զրույց',
  'Nova senha': 'Նոր գաղտնաբառ',
  'Dia e noite': 'Ցերեկ և գիշեր',
  'O avatar limpo, como sempre foi.': 'Ավատարը մաքուր, ինչպես միշտ։',
  'O canal sai da vista de todos com as mensagens dentro. Dá para trazer de volta por {dias} dias, em Configurações → Comunidade → Lixeira.':
    'Ալիքն անհետանում է բոլորի աչքից՝ հաղորդագրությունների հետ միասին։ Կարող ես վերադարձնել {dias} օրվա ընթացքում՝ Կարգավորումներ → Համայնք → Աղբարկղ։',
  'O cartão liso.': 'Հարթ քարտը։',
  'O céu inteiro girando bem devagar.': 'Ամբողջ երկինքը՝ շատ դանդաղ պտտվող։',
  'O clipe ficou grande demais para o chat. Escolha um trecho menor.': 'Հոլովակը չափազանց մեծ ստացվեց զրույցի համար։ Ընտրիր ավելի կարճ հատված։',
  'O navegador bloqueou as notificações deste site. Libere no cadeado ao lado do endereço e recarregue a página.':
    'Դիտարկիչն արգելափակել է այս կայքի ծանուցումները։ Թույլատրիր հասցեի կողքի կողպեքից և վերաբեռնիր էջը։',
  'O nome como sempre foi.': 'Անունը, ինչպես միշտ։',
  'o nome exato da pessoa': 'մարդու ճշգրիտ անունը',
  'O nome levanta um pouco do fundo.': 'Անունը մի քիչ բարձրանում է ֆոնից։',
  'O nome muda de cor devagar.': 'Անունը դանդաղ փոխում է գույնը։',
  'O que aconteceu?': 'Ի՞նչ է եղել',
  'O que dizer': 'Ինչ ասել',
  'O que tem dentro': 'Ինչ կա ներսում',
  'O que tem dentro do pacote': 'Ինչ կա փաթեթի ներսում',
  'O que vamos jogar hoje?': 'Ի՞նչ ենք խաղում այսօր',
  'O que você fez a respeito?': 'Ի՞նչ արեցիր դրա կապակցությամբ',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.':
    'Կնիքը կհայտնվի այստեղ, երբ առաջին հանգրվանը նվաճվի։ Մինչ այդ այն պահված է — և դրան հասնելն էլ հենց այն է, ինչ այն կնշանակի։',
  'O selo desta comunidade é': 'Այս համայնքի կնիքն է՝',
  'O servidor demorou demais para responder. Tente de novo.': 'Սերվերը չափազանց երկար պատասխանեց։ Փորձիր նորից։',
  'O som chega quando você abre esta transmissão.': 'Ձայնը կգա, երբ բացես այս հեռարձակումը։',
  'O survival do Léo': 'Լևոնի survival սերվերը',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.':
    'Syden-ն արդեն կարողանում է գրել այս լեզուներից ցանկացածով — պակասում է տեքստերի թարգմանությունը։ Քանի դեռ այն չկա, չթարգմանվածը երևում է պորտուգալերեն, իսկ յուրաքանչյուր այբուբենի տառերը ճիշտ են երևում՝ առանց քառակուսիների։',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'Syden-ը մոտ 10 րոպե հասանելի չի լինի՝ թարմացման պատճառով։',
  'Observação': 'Նշում',
  'Oceania': 'Օվկիանիա',
  'Oceano': 'Օվկիանոս',
  'Offline': 'Անցանց',
  'Olhe o seu e-mail': 'Ստուգիր էլ. փոստդ',
  'Opções': 'Ընտրանքներ',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.':
    'Ներքևի հանգրվաններն ընտրվել են այնպես, որ անհնար լինի դրանց հասնել մենակ — բոլորին պետք է մեկից ավելի մարդ՝ ժամանակի ընթացքում։',
  'Os outros idiomas': 'Մյուս լեզուները',
  'Os outros passam a ouvir o efeito na hora. Você continua sem se escutar.':
    'Մյուսներն անմիջապես լսում են էֆեկտը։ Դու շարունակում ես քեզ չլսել։',
  'ou': 'կամ',
  'ou cole um link (MyInstants, por exemplo)': 'կամ զետեղիր հղում (օրինակ՝ MyInstants)',
  'Ouça antes de enviar:': 'Լսիր նախքան ուղարկելը:',
  'Ouro': 'Ոսկի',
  'Outros aparelhos': 'Այլ սարքեր',
  'Ouvir': 'Լսել',
  'Ouvir esta transmissão de novo': 'Կրկին լսել այս հեռարձակումը',
  'Pacote do Syden': 'Syden-ի փաթեթ',
  'Pacotes': 'Փաթեթներ',
  'Pacotes de sons e de emojis': 'Հնչյունների և էմոջիների փաթեթներ',
  'Padrão': 'Ստանդարտ',
  'Padrão do sistema': 'Ըստ համակարգի',
  'Páginas abertas': 'Բացված էջեր',
  'Painéis do servidor': 'Սերվերի վահանակներ',
  'Para jogos. Manda uma imagem só, a melhor: sobra máquina para o jogo, e quem assiste recebe o que ela é.':
    'Խաղերի համար։ Ուղարկում է միայն մեկ պատկեր՝ լավագույնը․ համակարգչի ուժն ավելի շատ է մնում խաղին, և դիտողները ստանում են այն, ինչ կա։',
  'Parar': 'Կանգնեցնել',
  'Parar de assistir esta transmissão': 'Դադարել դիտել այս հեռարձակումը',
  'Parar o som para todos na sala': 'Կանգնեցնել հնչյունը սենյակում բոլորի համար',
  'Parar teste': 'Կանգնեցնել փորձարկումը',
  'Pedidos que você enviou': 'Քո ուղարկած հայտերը',
  'pela placa de vídeo': 'վիդեոքարտով',
  'pelo processador': 'պրոցեսորով',
  'Pergunta': 'Հարց',
  'Período': 'Ժամանակահատված',
  'Permitir acesso para ver os dispositivos': 'Թույլատրել մուտքը՝ սարքերը տեսնելու համար',
  'Pessoa': 'Մարդ',
  'Pessoa não encontrada.': 'Մարդը չի գտնվել։',
  'Pessoas': 'Մարդիկ',
  'Pessoas bloqueadas': 'Արգելափակված մարդիկ',
  'Pessoas das suas comunidades': 'Մարդիկ քո համայնքներից',
  'PNG, JPG ou WEBP, de qualquer tamanho: você escolhe o recorte. GIF animado vai inteiro, até 5 MB.': 'PNG, JPG կամ WEBP՝ ցանկացած չափի․ կտրվածքը դու ես ընտրում։ Անիմացիոն GIF-ը գնում է ամբողջությամբ՝ մինչև 5 ՄԲ։',
  'O GIF do avatar pode ter até 5 MB.': 'Ավատարի GIF-ը կարող է լինել մինչև 5 ՄԲ։',
  'Ou cole o link de um GIF ou de uma imagem, do Tenor e do GIPHY também. O Syden baixa uma cópia e guarda.': 'Կամ տեղադրիր GIF-ի կամ պատկերի հղումը, նաև Tenor-ից և GIPHY-ից։ Syden-ը ներբեռնում է պատճենը և պահում։',
  'Essa página não tem uma imagem para usar. Copie o link da imagem.': 'Այդ էջում օգտագործելու պատկեր չկա։ Պատճենիր պատկերի հղումը։',
  'Muitos links seguidos. Tente de novo daqui a pouco.': 'Չափազանց շատ հղումներ իրար հետևից։ Փորձիր նորից մի քիչ հետո։',
  'PNG, JPG, WEBP ou GIF animado, até 512 KB. A imagem é ajustada para 128×128.':
    'PNG, JPG, WEBP կամ անիմացիոն GIF՝ մինչև 512 ԿԲ։ Պատկերը հարմարեցվում է 128×128 չափին։',
  'Poeira de estrelas, roxa e azul.': 'Աստղափոշի՝ մանուշակագույն և կապույտ։',
