  'Procurar GIF': 'Որոնել GIF',
  'Progresso de {marco}': 'Առաջընթաց՝ {marco}',
  'Pronto: só este aparelho continua conectado.': 'Պատրաստ է․ միացված է մնում միայն այս սարքը։',
  'Pronto. Quem entrar agora vai ver isto.': 'Պատրաստ է։ Այժմ մտնողները կտեսնեն սա։',
  'Pulso': 'Զարկ',
  'Qualidade do compartilhamento de tela': 'Էկրանի ցուցադրման որակ',
  'Quatro caracteres, um ícone e uma cor que aparecem ao lado do nome de quem é daqui.':
    'Չորս նիշ, պատկերակ և գույն, որոնք երևում են այստեղի բոլոր անդամների անվան կողքին։',
  'Que bom te ver de novo.': 'Ուրախ եմ քեզ նորից տեսնել։',
  'Que legal!': 'Ինչ լավ է։',
  'Jogando agora': "Հիմա խաղում են",
  'Estou aqui': "Ես այստեղ եմ",
  'Ao abrir o Syden': "Syden-ը բացելիս",
  'No quarto': "Սենյակում",
  'Onde parei': "Վերջին տեղում",
  'Aniversário do Syden': "Syden-ի ծննդյան օրը",
  'Hoje é aniversário do Syden!': "Այսօր Syden-ի ծննդյան օրն է։",
  'O Syden nasceu em {data}. Valeu por fazer parte desta história.': "Syden-ը ծնվել է {data}։ Շնորհակալ ենք, որ այս պատմության մասն ես։",
  'Quem mais cantou': "Ով է ամենաշատը երգել",
  'Mais cantadas': "Ամենաշատ երգվածները",
  'Músicas cantadas: {n}': "Երգված երգեր՝ {n}",
  'Ninguém cantou ainda. Conta quando alguém põe uma música com a turma na sala.': "Դեռ ոչ ոք չի երգել։ Հաշվվում է, երբ ինչ-որ մեկը երգ է միացնում, երբ խումբը սենյակում է։",
  'Idiomas': "Լեզուներ",
  'Idiomas falados': "Խոսվող լեզուներ",
  'Idiomas em estudo': "Ուսումնասիրվող լեզուներ",
  'Aparece no seu cartão de perfil, para quem fala um idioma achar quem o estuda. É opcional.': "Երևում է քո պրոֆիլի քարտում, որպեսզի լեզուն խոսողը գտնի այն սովորողին։ Պարտադիր չէ։",
  'Feliz aniversário, {nome}!': 'Ծնունդդ շնորհավոր, {nome}։',
  'Que este ano venha cheio de boas conversas, boas partidas e boa companhia.': 'Թող այս տարին լի լինի լավ զրույցներով, լավ խաղերով ու լավ ընկերակցությամբ։',
  'Quem abre o site': 'Ով է բացում կայքը',
  'Quem anda com você': 'Ով է քեզ հետ',
  'Quem bloqueia é o Windows. Abra Configurações do Windows → Privacidade e segurança → Microfone e ligue o acesso para o navegador.':
    'Արգելափակողը Windows-ն է։ Բացիր Windows-ի Կարգավորումներ → Գաղտնիություն և անվտանգություն → Խոսափող և միացրու մուտքը դիտարկիչի համար։',
  'Quem canta': 'Ով է երգում',
  'quem cuida do Syden': 'Syden-ին խնամողները',
  'Quem cuida do Syden vai olhar. Obrigado por avisar.': 'Syden-ին խնամողները կնայեն։ Շնորհակալություն, որ տեղեկացրիր։',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.':
    'Այստեղ գտնվողները չեն տեսնում քո հաղորդագրությունները, ոչ էլ դու՝ նրանցը, չեն կարող անձնական զրույց բացել քեզ հետ և չեն կարող քեզ ընկերության հայտ ուղարկել։',
  'Quem estiver na sala será desconectado. Dá para trazer a sala de volta por {dias} dias, em Configurações → Comunidade → Lixeira.':
    'Սենյակում գտնվողները կանջատվեն։ Կարող ես վերադարձնել սենյակը {dias} օրվա ընթացքում՝ Կարգավորումներ → Համայնք → Աղբարկղ։',
  'Quem falou': 'Ով է խոսել',
  'Quem tiver este código entra na comunidade: pela tela de cadastro, se ainda não tem conta, ou pelo botão de entrar, se já usa o Syden.':
    'Այս կոդն ունեցողը մտնում է համայնք՝ գրանցման էջից, եթե դեռ հաշիվ չունի, կամ մտնելու կոճակով, եթե արդեն օգտագործում է Syden-ը։',
  'Quente, mas sem gritar.': 'Տաք, բայց ոչ աղմկոտ։',
  'Querem falar': 'Ուզում են խոսել',
  'Rádio de avião': 'Ինքնաթիռի ռադիո',
  'Recado': 'Ուղերձ',
  'Quem dá o recado': 'Ով է փոխանցում ուղերձը',
  'Recomendado para a maioria. Quem assiste pode baixar a qualidade se precisar.':
    'Առաջարկվում է մեծամասնությանը։ Դիտողները կարող են իջեցնել որակը, եթե պետք լինի։',
  'Recompensa': 'Պարգև',
  'Código secreto': 'Գաղտնի կոդ',
  'Achou o código que só quem procura acha': 'Գտավ այն կոդը, որը գտնում է միայն փնտրողը',
  'Você achou o código secreto. Os melhores segredos são de quem procura.':
    'Դու գտար գաղտնի կոդը։ Լավագույն գաղտնիքները պատկանում են նրանց, ովքեր փնտրում են։',
  'Segredo': 'Գաղտնիք',
  'Reconectando ao servidor…': 'Նորից միանում է սերվերին…',
  'Reduz barulhos de fundo, como teclado, ventilador e trânsito.': 'Նվազեցնում է ֆոնային աղմուկը՝ ստեղնաշար, օդափոխիչ, փողոցի երթևեկություն։',
  'Registro': 'Գրանցամատյան',
  'Registro de moderação': 'Մոդերացիայի գրանցամատյան',
