  'Resgatar': 'Ակտիվացնել',
  'Resolver': 'Լուծել',
  'Responder no tópico': 'Պատասխանել ճյուղում',
  'Respostas': 'Պատասխաններ',
  'Restaurando…': 'Վերականգնվում է…',
  'Restaurar o pacote': 'Վերականգնել փաթեթը',
  'Resultados': 'Արդյունքներ',
