  'Sair da conta': 'Ելնել հաշվից',
  'Sair da tela cheia': 'Դուրս գալ լիաէկրանից',
  'Sair de {comunidade}? As suas mensagens continuam lá para quem ficou.':
    'Դուրս գա՞լ {comunidade} համայնքից։ Քո հաղորդագրությունները կմնան այնտեղ մնացածների համար։',
  'Sair dos outros aparelhos': 'Դուրս գալ մյուս սարքերից',
