  'Saúde do servidor': 'Սերվերի առողջություն',
  'Se existir uma conta com esse endereço, o link para escolher uma senha nova chegou lá. Ele vale por 1 hora.':
    'Եթե այդ հասցեով հաշիվ կա, նոր գաղտնաբառ ընտրելու հղումն արդեն այնտեղ է։ Այն գործում է 1 ժամ։',
  'Selo da comunidade': 'Համայնքի կնիք',
  'Selo que você veste': 'Կնիքը, որ կրում ես',
