  'Vermelho profundo, com pulso.': 'Խոր կարմիր՝ զարկով։',
  'Versalete': 'Փոքր գլխատառեր',
  'Versão 1.21, sem PvP': 'Տարբերակ 1.21, առանց PvP',
  'Vídeo': 'Տեսանյութ',
  'Vidro colorido com a luz passando.': 'Գունավոր ապակի՝ միջով անցնող լույսով։',
  'Vila': 'Գյուղ',
  'Visitas': 'Այցելություններ',
  'Vitral': 'Վիտրաժ',
  'você': 'դու',
  'Você ainda não está em nenhuma comunidade': 'Դու դեռ ոչ մի համայնքում չես',
  'Você ainda não tem amigos no Syden. A aba': 'Syden-ում դեռ ընկերներ չունես։ Բաժին՝',
  'Você ainda não tem este item': 'Դու դեռ չունես այս իրը',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.':
    'Դեռ ոչ մեկը չունես։ Դրանք գալիս են որպես նվեր կամ պարգև — օրինակ, երբ քո գաղափարը մտնում է Syden։',
  'Você chegou no começo de tudo. Obrigado por estar aqui desde quando isto era só uma ideia entre amigos.':
    'Դու եկար ամենասկզբում։ Շնորհակալություն, որ այստեղ ես այն ժամանակվանից, երբ սա դեռ միայն գաղափար էր ընկերների միջև։',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.':
    'Դու մտել ես արտաքին ծառայության միջոցով, և այս հաշիվը դեռ գաղտնաբառ չունի։ Սահմանիր այստեղ․ այն կդառնա մուտքի երկրորդ ճանապարհ, և հենց դա կթույլ տա հետո անջատել այդ ծառայությունը։',
  'Você está silenciado!': 'Քո խոսափողը լռեցված է։',
  'Você foi convidado. É só escolher um nome, um e-mail e uma senha.': 'Քեզ հրավիրել են։ Պարզապես ընտրիր անուն, էլ. փոստ և գաղտնաբառ։',
  'Você não bloqueou ninguém.': 'Դու ոչ ոքի չես արգելափակել։',
  'Você não enviou nenhum pedido.': 'Դու ոչ մի հայտ չես ուղարկել։',
  'Você não participa desta comunidade.': 'Դու այս համայնքում չես։',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.':
    'Կկորցնես այս համայնքի ալիքների հասանելիությունը։ Վերադառնալու համար նոր հրավեր պետք կլինի։',
  'Você recebeu um item': 'Նոր իր ես ստացել',
