  'Volume da transmissão': 'Հեռարձակման ձայնի ուժգնություն',
  'Volume do soundboard (só para você): {quanto}%': 'Հնչյունների վահանակի ուժգնություն (միայն քեզ համար)՝ {quanto}%',
