  'Mostrar a lista de pessoas': 'Ցույց տալ մարդկանց ցանկը',
  'Sair do modo sessão': 'Դուրս գալ միասին դիտելու ռեժիմից',
  'Assistir junto: vídeo grande e conversa ao lado': 'Դիտել միասին․ մեծ տեսանյութ, իսկ զրույցը՝ կողքին',
  'Assistir junto': 'Դիտել միասին',
