  'Marcar {nome} como favorito': 'Նշել որպես ընտրյալ՝ {nome}',
  'Volume do soundboard': 'Հնչյունների վահանակի ուժգնություն',
  'Procurar som': 'Որոնել հնչյուն',
  'Nenhum som ainda. Adicione um abaixo, ou instale um pacote em Configurações → Soundboard.': 'Դեռ հնչյուններ չկան։ Ավելացրու մեկը ներքևում կամ տեղադրիր փաթեթ՝ Կարգավորումներ → Հնչյունների վահանակ։',
  'está transmitindo {oque}': 'հեռարձակում է՝ {oque}',
  'está transmitindo': 'հեռարձակում է',
  'Clique para ativar o áudio': 'Սեղմիր՝ ձայնը միացնելու համար',
  'Focar em uma transmissão': 'Կենտրոնանալ մեկ հեռարձակման վրա',
  'Ver as {n} transmissões lado a lado': 'Տեսնել {n} հեռարձակումները կողք կողքի',
  'Todos do mesmo tamanho': 'Բոլորը նույն չափով',
  'Tela inteira': 'Ամբողջ էկրանը',
  'Tudo o que está na tela. O som do computador vai junto, já sem as vozes desta chamada.': 'Այն ամենը, ինչ էկրանին է։ Համակարգչի ձայնը գնում է հետը՝ արդեն առանց այս զանգի ձայների։',
  'Tudo o que está na tela. Para ir com som, marque "compartilhar áudio do sistema" na janelinha do navegador.': 'Այն ամենը, ինչ էկրանին է։ Որ ձայնով գնա, դիտարկիչի փոքր պատուհանում նշիր «Կիսվել համակարգի աուդիոյով»։',
  'Uma janela ou app': 'Պատուհան կամ հավելված',
  'Só aquele programa, e o som do computador vai junto mesmo assim.': 'Միայն այդ ծրագիրը, և համակարգչի ձայնը միևնույն է գնում է հետը։',
  'Opções da transmissão': 'Հեռարձակման ընտրանքներ',
  'Compartilhar tela': 'Կիսվել էկրանով',
  'Trocar para…': 'Անցնել…',
  'O que compartilhar?': 'Ինչո՞վ կիսվել',
  'O som do computador vai junto sozinho.': 'Համակարգչի ձայնը գնում է ինքնաբերաբար։',
  'No navegador, o som só vai se você marcar a caixinha de áudio na janelinha que abrir. No app do Syden ele vai sozinho.': 'Դիտարկիչում ձայնը գնում է միայն այն դեպքում, եթե բացվող փոքր պատուհանում նշես աուդիոյի վանդակը։ Syden-ի հավելվածում այն գնում է ինքնաբերաբար։',
