  'Parece o mesmo som que «{nome}».': 'Կարծես նույն ձայնն է, ինչ «{nome}»-ը։',
  'Procurar sons repetidos': 'Գտնել կրկնվող ձայները',
  'Nenhum som repetido.': 'Կրկնվող ձայներ չկան։',
  'Cada grupo parece ser o mesmo som. Ouça e exclua o que sobrar.': 'Յուրաքանչյուր խումբ կարծես նույն ձայնն է։ Լսիր և ջնջիր ավելորդը։',
  'Link da sala': 'Սենյակի հղում',
  'Para quem é da turma: entra na comunidade e cai direto nesta sala.': 'Ընկերներիդ համար․ միանում են համայնքին և ուղիղ հայտնվում այս սենյակում։',
  'Visitante sem conta': 'Այցելու՝ առանց հաշվի',
  'Entra só com o nome, sem virar membro, e sai quando o link vence.': 'Մտնում է միայն անունով, առանց անդամ դառնալու, և դուրս է գալիս, երբ հղումը լրանում է։',
