  'Ao lado de um objeto de tamanho conhecido aparece outro, e cada um aumenta ou diminui esse outro até achar o tamanho certo. Quem chegar mais perto ganha mais pontos.': 'Հայտնի չափի առարկայի կողքին հայտնվում է մեկ ուրիշը, և յուրաքանչյուրը մեծացնում կամ փոքրացնում է այն, մինչև գտնի ճիշտ չափը։ Ով ամենամոտն է, ամենաշատ միավորն է ստանում։',
  'Arraste para aumentar ou diminuir.': 'Քաշիր՝ մեծացնելու կամ փոքրացնելու համար։',
  'Confirmar': 'Հաստատել',
  'Confirmado. {n} de {total} já confirmaram.': 'Հաստատված է։ {total}-ից {n}-ն արդեն հաստատել են։',
  '+{n} pontos': '+{n} միավոր',
  'Escolha a sala para jogar com a turma:': 'Ընտրիր սենյակը՝ ընկերների հետ խաղալու համար․',
  'Para jogar fora e transmitir': 'Դրսում խաղալու և հեռարձակելու համար',
  'Rodada {n} de {total}': 'Ռաունդ {n} / {total}',
  'Fim de jogo!': 'Խաղն ավարտվեց',
  'Jogar de novo': 'Խաղալ նորից',
  'Encerrar partida': 'Ավարտել խաղը',
  'Você não votou nesta.': 'Այս մեկի համար չես քվեարկել։',
  'Só aquele programa, sem som: o navegador não pega o som de uma janela. Para ir com som, use a tela inteira.': 'Միայն այդ ծրագիրը, առանց ձայնի․ դիտարկիչը չի որսում պատուհանի ձայնը։ Ձայնով ուղարկելու համար ընտրիր ամբողջ էկրանը։',
  'Na sala de voz, com a turma': 'Ձայնային սենյակում, ընկերների հետ',
  'Esperando alguém da sala sentar do outro lado…': 'Սպասում ենք, որ սենյակից ինչ-որ մեկը նստի դիմացը…',
  '{nome} quer jogar. Sente do outro lado!': '{nome} ուզում է խաղալ։ Նստիր դիմացը։',
  'Sua vez!': 'Քո հերթն է։',
  'Vez de {nome}.': 'Հերթը՝ {nome}։',
  'Empate!': 'Ոչ-ոքի։',
  'Ninguém sentou para jogar.': 'Ոչ ոք չնստեց խաղալու։',
  '{nome} demorou demais para jogar. {vencedor} venceu!': '{nome} չափազանց երկար մտածեց։ Հաղթեց {vencedor}։',
  '{nome} desistiu. {vencedor} venceu!': '{nome} հանձնվեց։ Հաղթեց {vencedor}։',
  '{nome} venceu!': 'Հաղթեց {nome}։',
  'Jogar': 'Խաղալ',
  'Desistir': 'Հանձնվել',
  'Letra: {letra}': 'Տառ՝ {letra}',
  '{n} de {total} já completaram.': '{n} / {total} արդեն լրացրել են։',
  'Preencha todas as categorias antes de parar.': 'Լրացրու բոլոր կատեգորիաները՝ նախքան կանգնեցնելը։',
  'STOP': 'ՍՏՈՊ',
  '{nome} apertou STOP!': '{nome} սեղմեց ՍՏՈՊ։',
  'Clique numa resposta que não vale. Ela cai se mais da metade concordar.': 'Սեղմիր այն պատասխանի վրա, որը չի հաշվվում։ Այն կհանվի, եթե կեսից ավելին համաձայնի։',
  'Pontos da rodada': 'Ռաունդի միավորները',
  'Desfazer': 'Հետարկել',
  'Não vale': 'Չի հաշվվում',
  '{n} de {total} prontos.': '{n} / {total} պատրաստ են։',
  'Você terminou! Agora é torcer pelos outros.': 'Ավարտեցիր։ Հիմա մնում է երկրպագել մյուսներին։',
  'Outros jogos': 'Այլ խաղեր',
  'Stop': 'Ստոպ',
  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'Ընտրվում է մի տառ, և յուրաքանչյուրը յուրաքանչյուր կատեգորիայում գրում է այդ տառով սկսվող բառ։ Ով առաջինն ավարտի, սեղմում է ՍՏՈՊ, և ընկերները որոշում են, թե ինչն է հաշվվում։',
  'Sudoku': 'Սուդոկու',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'Բոլորը ստանում են նույն սուդոկուն, և սենյակը տեսնում է, թե ով է ավարտին ավելի մոտ։',
  'Cinco em linha': 'Հինգը շարքով',
  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'Երկու հոգի հերթով քարեր են դնում տախտակին։ Հաղթում է նա, ով հինգը շարքով կդասավորի։ Սենյակը դիտում է։',
  'Mancala': 'Մանկալա',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'Ցանելու խաղը․ վերցրու մի փոսի սերմերը և մեկական դիր հաջորդ փոսերում։ Հաղթում է նա, ով իր պահեստում ավելի շատ կհավաքի։ Սենյակը դիտում է։',
  'Nome de pessoa': 'Անձի անուն',
  'Animal': 'Կենդանի',
  'Fruta': 'Միրգ',
  'Objeto': 'Առարկա',
  'Cidade, estado ou país': 'Քաղաք, նահանգ կամ երկիր',
