  'O Lobisomem precisa de pelo menos 4 pessoas na sala.': 'Մարդագայլի համար սենյակում պետք է առնվազն 4 մարդ։',
  'Esta partida começou sem você. Espere a próxima.': 'Այս խաղն սկսվեց առանց քեզ։ Սպասիր հաջորդին։',
  'Quem saiu do jogo só assiste.': 'Խաղից դուրս եկածները միայն դիտում են։',
