  'sem notas ainda': 'Գնահատականներ դեռ չկան',
  '1 emoji saiu de {comunidade}.': '{comunidade}-ից հանվեց 1 էմոջի։',
  '{n} emojis saíram de {comunidade}.': '{comunidade}-ից հանվեցին {n} էմոջի։',
  '1 emoji entrou. Ficaram de fora, porque a comunidade já tem esses nomes: {nomes}': 'Ավելացավ 1 էմոջի։ Դուրս մնացին այս անունները, քանի որ համայնքում դրանք արդեն կան՝ {nomes}',
  '{n} emojis entraram. Ficaram de fora, porque a comunidade já tem esses nomes: {nomes}': 'Ավելացան {n} էմոջի։ Դուրս մնացին այս անունները, քանի որ համայնքում դրանք արդեն կան՝ {nomes}',
  'Pronto: 1 emoji entrou em {comunidade}.': 'Պատրաստ է՝ {comunidade}-ում ավելացավ 1 էմոջի։',
  'Pronto: {n} emojis entraram em {comunidade}.': 'Պատրաստ է՝ {comunidade}-ում ավելացան {n} էմոջի։',
