  'Pessoas diferentes que já estiveram numa call com alguém.': 'Տարբեր մարդիկ, ովքեր արդեն եղել են զանգում ինչ-որ մեկի հետ։',
  'Pessoas diferentes que já jogaram uma partida.': 'Տարբեր մարդիկ, ովքեր արդեն խաղացել են մեկ խաղարկություն։',
