  'Desvie das sementes e derrube a praga. O espantalho vem no fim.': 'Խուսափիր սերմերից և խփիր վնասատուներին։ Խրտվիլակը գալիս է վերջում։',
  'Sem vidas: agora é torcer pela esquadrilha.': 'Կյանքեր չմնացին․ հիմա քաջալերիր էսկադրիլիային։',
