  'O tempo acabou: ganhou quem tinha mais.': 'Ժամանակն ավարտվեց՝ հաղթեց նա, ով ավելին ուներ։',
  'A sua Maravilha ficou de pé por 2 minutos.': 'Քո Հրաշալիքը կանգուն մնաց 2 րոպե։',
  'A Maravilha do computador ficou de pé por 2 minutos.': 'Համակարգչի Հրաշալիքը կանգուն մնաց 2 րոպե։',
  'Você derrubou o centro da vila do computador.': 'Դու քանդեցիր համակարգչի գյուղի կենտրոնը։',
  'O computador derrubou o seu centro da vila.': 'Համակարգիչը քանդեց քո գյուղի կենտրոնը։',
  'Você avançou para a era 2!': 'Դու անցար 2-րդ դարաշրջան։',
  'O computador avançou para a era 2.': 'Համակարգիչն անցավ 2-րդ դարաշրջան։',
  'A sua Maravilha está pronta: defenda-a por 2 minutos!': 'Քո Հրաշալիքը պատրաստ է՝ պաշտպանիր այն 2 րոպե։',
  'O computador terminou uma Maravilha: derrube-a em 2 minutos!': 'Համակարգիչն ավարտեց Հրաշալիքը՝ քանդիր այն 2 րոպեում։',
