  'Este jogo não se joga na sala.': 'Այս խաղը սենյակում չի խաղացվում։',
  'Ponha os seus navios no mar.': 'Տեղադրիր քո նավերը ծովում։',
  'Esperando {nome} pôr os navios…': 'Սպասում ենք, մինչև {nome} տեղադրի նավերը…',
  'Os dois estão pondo os navios…': 'Երկուսն էլ տեղադրում են իրենց նավերը…',
  'Navio de {n} casas': '{n} վանդակով նավ',
  'Seus navios': 'Քո նավերը',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'Ընտրիր նավ և հպիր ծովին։ Քաշիր՝ տեղը փոխելու համար։',
  'Sortear a frota': 'Պատահական նավատորմ',
  'Sua frota já está pronta.': 'Քո նավատորմն արդեն պատրաստ է։',
  'Ponha todos os navios antes.': 'Նախ տեղադրիր բոլոր նավերը։',
  'Escolha um navio.': 'Ընտրիր նավ։',
  'O navio não cabe aí.': 'Նավն այնտեղ չի տեղավորվում։',
  'Os navios não podem encostar um no outro.': 'Նավերը չեն կարող իրար դիպչել։',
  'Minigolfe 3D': 'Մինիգոլֆ 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Ութ անցք 3D-ով, թեքահարթակներով, դղյակով ու հողմաղացով, բոլորը միաժամանակ նույնն են խաղում։ Քաշիր՝ նշան բռնելու և ուժ տալու համար, ու բաց թող։ Հաղթում է նա, ով ընդհանուր առմամբ ամենաքիչ հարվածն ունի։',
  'Ver o buraco de cima': 'Նայել անցքին վերևից',
  'Fora da pista! Mais uma tacada.': 'Ուղուց դուրս։ Եվս մեկ հարված։',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Քաշիր կողք՝ նշան բռնելու, և ներքև՝ ուժի համար, ու բաց թող։ Ստեղնաշարով՝ սլաքներով նշան ես բռնում, իսկ սեղմած պահված բացատը ուժ է տալիս։',
  'Futebol dos coelhos': 'Ճագարների ֆուտբոլ',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Փոքր դաշտի ֆուտբոլ՝ վերևից։ Դիպիր գնդակին՝ այն վարելու համար, սեղմած պահիր բացատը՝ ավելի ուժեղ հարվածելու համար, և փոխանցիր X-ով։ Սենյակում թիմերը լրացվում են ռոբոտներով։',
  'Quantos por time?': 'Քանի՞ հոգի թիմում',
