  'Caça às pragas da horta': 'Բանջարանոցի վնասատուների որս',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Ագռավներն ու մորեխները հարձակվում են բանջարանոցի վրա։ Նշան բռնիր և սեղմիր՝ խփելու համար, մինչև կփախչեն․ զինամթերքը հաշված է, և ամեն ալիք ավելի արագ է գալիս։ Հաղթում է նա, ով ամենաշատ միավորն է հավաքում։',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Նշան բռնիր և սեղմիր վնասատուների վրա, մինչև կփախչեն։ Ամեն կրակոց մեկ գազար է ծախսում։',
