  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Շրջիր Բրազիլիայի մայրաքաղաքներով, գնիր քաղաքներ և վարձ գանձիր նրանցից, ովքեր կանգնում են դրանց վրա։ Ամբողջ տարածաշրջանն ունենալով՝ կարող ես շենքեր կառուցել։ Փոխանակիր, մրցիր աճուրդներում և մի մնա առանց փողի։',
