  'Figurinha não encontrada.': 'Սթիքերը չի գտնվել։',
  'A sua coleção de figurinhas está cheia. Tire alguma para pôr outra.': 'Սթիքերների քո հավաքածուն լցված է։ Նորը դնելու համար հանիր որևէ մեկը։',
  'Figurinha': 'Սթիքեր',
