  'Contorno': 'Եզրագիծ',
  'O fundo não é de uma cor só, e ficou como veio.': 'Ֆոնը միագույն չէ, ուստի մնաց այնպես, ինչպես կար։',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'Syden հավելվածում հեռացումն աշխատում է ցանկացած ֆոնի հետ։',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'Մոդելով հեռացումը ձախողվեց, ուստի օգտագործվեց պարզ հեռացումը։',
