  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'Ստեղծիր սթիքերներ քո պատկերներից կամ պահպանիր զրույցում ստացածները։',
  'Dominó': 'Դոմինո',
  'Truco': 'Տրուկո',
