  'Batalha naval': 'Ծովամարտ',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Սովորական դոմինո՝ 2–4 հոգով (4-ով՝ զույգերով)։ Քարերը կցիր ծայրերին, և ով առաջինը վերջացնի, կվերցնի մյուսների ձեռքի միավորները։',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Պաուլիստա տրուկո՝ բաց քարտով և հաղթաթղթերով, 2 հոգով կամ 4 հոգով զույգերով։ Պահանջիր տրուկո, բարձրացրու մինչև վեց, ինը և տասներկու, կամ փախիր։ Հաղթում է նա, ով 12 միավոր է հավաքում։',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Բրազիլական շաշկի․ ուտելը պարտադիր է՝ առաջ և հետ, իսկ դաման շարժվում է ամբողջ անկյունագծով։ Սենյակը դիտում է։',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Յուրաքանչյուրը թաքցնում է իր նավատորմը և կրակում մյուսի ծովին։ Խփեցիր՝ կրակում ես նորից։ Հաղթում է նա, ով առաջինը խորտակի ամբողջ նավատորմը։ Սենյակը դիտում է։',
