  'Uma partida de xadrez inteira, com todas as regras. Quem abre fica com as brancas. A sala assiste.': 'Ամբողջական շախմատային պարտիա՝ բոլոր կանոններով։ Ով սկսում է, խաղում է սպիտակներով։ Սենյակը դիտում է։',
