  "Ações no servidor": "Գործողություններ սերվերում",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Hetzner-ի պատմությունը՝ միացում, անջատում և վերագործարկում վահանակից կամ API-ով։ Այստեղ գործողություն չունեցող խափանումը այս ուղիներով չի առաջացել։",
