  "{nome} tem a palavra. Ouçam a defesa.": "Խոսքը {nome}-ինն է։ Լսեք պաշտպանությունը։",
  "{nome} terminou uma Maravilha: derrube-a em 2 minutos!": "{nome}-ն ավարտեց Հրաշալիքը․ քանդեք այն 2 րոպեում։",
  "{nome} tirou dados iguais e joga de novo.": "{nome}-ը գցեց նույն զառերը և նորից է խաղում։",
