  "1 contra 3": "1-ը 3-ի դեմ",
  "2 contra 2": "2-ը 2-ի դեմ",
  "A armadilha de {nome} disparou: quem sai junto?": "{nome}-ի թակարդը գործեց․ ո՞վ է դուրս գալիս միասին։",
  "A largada precisa de uma reta.": "Մեկնարկին ուղիղ հատված է պետք։",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "{nome}-ի Հրաշալիքը կանգուն մնաց 2 րոպե։",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Նույն դիրքը երրորդ անգամ՝ ոչ-ոքի, ինչպես նաև 20 քայլ միայն թագուհիներով առանց կերելու։",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Գիշերը տես, թե ում հարձակվեցին մարդագայլերը։ Մի ըմպելիքը փրկում է այդ մարդուն, մյուսը՝ հանում ինչ-որ մեկին խաղից․ յուրաքանչյուրը՝ մեկ անգամ։",
  "A partida se desencontrou entre os computadores e foi encerrada.": "Խաղը համակարգիչների միջև խառնվեց և ավարտվեց։",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "Վերջին շարքում քայլն ավարտող քարը դառնում է թագուհի, որը քայլում է ամբողջ անկյունագծով։",
  "A pista ainda não fecha a volta.": "Ճանապարհը դեռ չի փակում շրջանը։",
  "A pista está curta demais.": "Ճանապարհը չափազանց կարճ է։",
  "A pista passa por cima dela mesma.": "Ճանապարհն անցնում է իր վրայով։",
  "A pista precisa de mais peças.": "Ճանապարհին ավելի շատ մասեր են պետք։",
  "A turma age antes nas duas rodadas seguintes.": "Խումբը առաջինն է գործում հաջորդ երկու ռաունդում։",
  "A turma está decidindo.": "Խումբը որոշում է։",
  "A turma inteira leva bem menos dano nesta rodada.": "Ամբողջ խումբն այս ռաունդում շատ ավելի քիչ վնաս է ստանում։",
  "A turma recupera vida no fim de três rodadas.": "Խումբը կյանք է վերականգնում երեք ռաունդի վերջում։",
