  // Os mini-games e as insígnias (19/11/2026)
  "{nome} terminou uma Maravilha: defenda-a por 2 minutos!": "{nome}-ն ավարտեց Հրաշալիքը․ պաշտպանիր այն 2 րոպե։",
  "{nome} terminou uma Maravilha.": "{nome}-ն ավարտեց Հրաշալիքը։",
  "A Maravilha da outra equipe ficou de pé por 2 minutos.": "Մյուս թիմի Հրաշալիքը կանգուն մնաց 2 րոպե։",
  "A Maravilha da sua equipe ficou de pé por 2 minutos.": "Քո թիմի Հրաշալիքը կանգուն մնաց 2 րոպե։",
  "A outra equipe derrubou os dois centros da vila de vocês.": "Մյուս թիմը քանդեց ձեր գյուղի երկու կենտրոններն էլ։",
  "A outra equipe desistiu.": "Մյուս թիմը հանձնվեց։",
