  "No dominó de pontos, quem deixa as pontas somando 5, 10, 15… marca a soma na hora; a carroça na ponta conta as duas metades. A partida vai a 150.": "Միավորներով դոմինոյում նա, ով ծայրերի գումարը դարձնում է 5, 10, 15…, անմիջապես ստանում է այդ գումարը. ծայրում դրված դուբլը հաշվվում է երկու կեսով։ Խաղը մինչև 150 է։",
