  "No modo Juntos, a turma resolve o mesmo tabuleiro: cada número aparece para todos, na cor de quem o pôs.": "«Միասին» ռեժիմում խումբը լուծում է նույն տախտակը. յուրաքանչյուր թիվ երևում է բոլորին՝ այն դնողի գույնով։",
