  "Qual destes animais dá lã?": "Այս կենդանիներից ո՞րն է բուրդ տալիս։",
  "Qual destes animais dá leite?": "Այս կենդանիներից ո՞րն է կաթ տալիս։",
  "Qual destes animais é noturno?": "Այս կենդանիներից ո՞րն է գիշերային։",
  "Qual destes animais é um mamífero?": "Այս կենդանիներից ո՞րն է կաթնասուն։",
