  "Qual destes animais tem o pescoço mais comprido?": "Այս կենդանիներից ո՞րն ունի ամենաերկար վիզը։",
  "Qual destes animais tem tromba?": "Այս կենդանիներից ո՞րն ունի կնճիթ։",
  "Qual destes animais vive em água doce?": "Այս կենդանիներից ո՞րն է ապրում քաղցրահամ ջրում։",
  "Qual destes animais vive no polo sul?": "Այս կենդանիներից ո՞րն է ապրում Հարավային բևեռում։",
  "Qual destes é atraído por um ímã?": "Սրանցից ո՞րն է ձգվում մագնիսով։",
  "Qual destes é o mais leve?": "Սրանցից ո՞րն է ամենաթեթևը։",
  "Qual destes é o satélite natural da Terra?": "Սրանցից ո՞րն է Երկրի բնական արբանյակը։",
  "Qual destes é um esporte com bola?": "Սրանցից ո՞րն է գնդակով մարզաձև։",
  "Qual destes é um inseto?": "Սրանցից ո՞րն է միջատ։",
  "Qual destes é um instrumento de corda?": "Սրանցից ո՞րն է լարային գործիք։",
  "Qual destes é um instrumento de sopro?": "Սրանցից ո՞րն է փողային գործիք։",
