  "Qual destes é um meio de transporte que anda na água?": "Սրանցից ո՞րն է ջրով շարժվող փոխադրամիջոց։",
  "Qual destes é um metal?": "Սրանցից ո՞րն է մետաղ։",
  "Qual destes é um sentido do corpo?": "Սրանցից ո՞րն է մարդու զգայություններից մեկը։",
  "Qual destes legumes é verde?": "Այս բանջարեղեններից ո՞րն է կանաչ։",
  "Qual destes números é ímpar?": "Այս թվերից ո՞րն է կենտ։",
  "Qual destes números é par?": "Այս թվերից ո՞րն է զույգ։",
  "Qual é a estação mais fria do ano?": "Տարվա ո՞ր եղանակն է ամենացուրտը։",
  "Qual é a estrela mais próxima da Terra?": "Ո՞րն է Երկրին ամենամոտ աստղը։",
  "Qual é a forma de uma bola?": "Ի՞նչ ձև ունի գնդակը։",
  "Qual é a montanha mais alta do mundo?": "Ո՞րն է աշխարհի ամենաբարձր լեռը։",
  "Qual é o animal terrestre mais rápido?": "Ո՞րն է ամենաարագ ցամաքային կենդանին։",
  "Qual é o continente mais gelado?": "Ո՞րն է ամենացուրտ մայրցամաքը։",
  "Qual é o filhote da ovelha?": "Ինչպե՞ս է կոչվում ոչխարի ձագը։",
  "Qual é o filhote da vaca?": "Ինչպե՞ս է կոչվում կովի ձագը։",
  "Qual é o filhote do cavalo?": "Ինչպե՞ս է կոչվում ձիու ձագը։",
  "Qual é o ingrediente principal do pão?": "Ո՞րն է հացի հիմնական բաղադրիչը։",
  "Qual é o maior animal do mundo?": "Ո՞րն է աշխարհի ամենամեծ կենդանին։",
  "Qual é o maior deserto quente do mundo?": "Ո՞րն է աշխարհի ամենամեծ տաք անապատը։",
  "Qual é o maior país do mundo em área?": "Ո՞րն է տարածքով աշխարհի ամենամեծ երկիրը։",
  "Qual é o maior planeta do Sistema Solar?": "Ո՞րն է Արեգակնային համակարգի ամենամեծ մոլորակը։",
  "Qual é o mês mais curto do ano?": "Ո՞րն է տարվա ամենակարճ ամիսը։",
  "Qual é o oceano mais extenso do planeta?": "Ո՞րն է մոլորակի ամենամեծ օվկիանոսը։",
  "Qual é o rio com mais água do mundo?": "Ո՞րն է աշխարհի ամենաջրառատ գետը։",
  "Qual órgão bombeia o sangue pelo corpo?": "Ո՞ր օրգանն է արյունը մղում մարմնով։",
  "Qual planeta é conhecido como o planeta vermelho?": "Ո՞ր մոլորակն է հայտնի որպես կարմիր մոլորակ։",
  "Qual planeta fica mais perto do Sol?": "Ո՞ր մոլորակն է Արևին ամենամոտը։",
  "Qual sólido tem seis faces quadradas?": "Ո՞ր մարմինն ունի վեց քառակուսի նիստ։",
  "Quantas asas tem uma borboleta?": "Քանի՞ թև ունի թիթեռը։",
  "Quantas cores tem o arco-íris, na conta mais comum?": "Քանի՞ գույն ունի ծիածանը՝ ըստ ամենատարածված հաշվարկի։",
  "Quantas horas tem um dia?": "Քանի՞ ժամ ունի օրը։",
  "Quanto é dez menos três?": "Որքա՞ն է տասը հանած երեքը։",
  "Quanto é metade de dez?": "Որքա՞ն է տասի կեսը։",
  "Quanto é o dobro de seis?": "Որքա՞ն է վեցի կրկնապատիկը։",
  "Quanto é sete vezes oito?": "Որքա՞ն է յոթ անգամ ութը։",
  "Quanto é três mais quatro?": "Որքա՞ն է երեք գումարած չորսը։",
  "Quanto tempo a Terra leva para dar uma volta em torno do Sol?": "Որքա՞ն ժամանակում է Երկիրը մեկ պտույտ կատարում Արևի շուրջը։",
  "Quanto tempo a Terra leva para girar em torno de si mesma?": "Որքա՞ն ժամանակում է Երկիրը պտտվում իր առանցքի շուրջը։",
  "Quantos anos tem um século?": "Քանի՞ տարի ունի դարը։",
  "Quantos anos tem uma década?": "Քանի՞ տարի ունի տասնամյակը։",
  "Quantos braços tem um polvo?": "Քանի՞ շոշափուկ ունի ութոտնուկը։",
  "Quantos centímetros tem um metro?": "Քանի՞ սանտիմետր կա մեկ մետրում։",
  "Quantos dentes tem um adulto, normalmente?": "Սովորաբար քանի՞ ատամ ունի չափահաս մարդը։",
  "Quantos dias tem um ano que não é bissexto?": "Քանի՞ օր ունի ոչ նահանջ տարին։",
  "Quantos dias tem uma semana?": "Քանի՞ օր ունի շաբաթը։",
  "Quantos gramas tem um quilo?": "Քանի՞ գրամ կա մեկ կիլոգրամում։",
  "Quantos jogadores um time de futebol tem em campo?": "Քանի՞ խաղացող ունի ֆուտբոլային թիմը դաշտում։",
  "Quantos lados tem um hexágono?": "Քանի՞ կողմ ունի վեցանկյունը։",
  "Quantos lados tem um quadrado?": "Քանի՞ կողմ ունի քառակուսին։",
  "Quantos lados tem um triângulo?": "Քանի՞ կողմ ունի եռանկյունը։",
  "Quantos meses tem um ano?": "Քանի՞ ամիս ունի տարին։",
  "Quantos minutos tem uma hora?": "Քանի՞ րոպե ունի ժամը։",
  "Quantos ossos tem o corpo de um adulto?": "Քանի՞ ոսկոր ունի չափահասի մարմինը։",
  "Quantos segundos tem um minuto?": "Քանի՞ վայրկյան ունի րոպեն։",
  "Quatorze": "Տասնչորս",
  "Que animal carrega a casa nas costas?": "Ո՞ր կենդանին է իր տունը մեջքին կրում։",
  "Que animal tem listras pretas e brancas?": "Ո՞ր կենդանին ունի սև ու սպիտակ շերտեր։",
  "Que bicho faz teia?": "Ո՞ր կենդանին է ոստայն հյուսում։",
  "Que bicho produz mel?": "Ո՞ր կենդանին է մեղր պատրաստում։",
  "Que fruta é a base do guacamole?": "Ո՞ր միրգն է գուակամոլեի հիմքը։",
  "Que fruta é amarela e comprida?": "Ո՞ր միրգն է դեղին ու երկար։",
  "Que gás as plantas soltam no ar?": "Ո՞ր գազն են բույսերը արտանետում օդ։",
  "Que gás nós soltamos ao respirar?": "Ո՞ր գազն ենք արտաշնչում։",
  "Que instrumento tem teclas brancas e pretas?": "Ո՞ր գործիքն ունի սպիտակ և սև ստեղներ։",
  "Que planeta tem anéis bem visíveis?": "Ո՞ր մոլորակն ունի լավ տեսանելի օղակներ։",
  "Recorde: {n} lances": "Ռեկորդ՝ {n} քայլ",
  "Rei e dama contra rei": "Արքա և թագուհի արքայի դեմ",
  "Rei e peão contra rei": "Արքա և զինվոր արքայի դեմ",
  "Rei e torre contra rei": "Արքա և նավակ արքայի դեմ",
  "Réptil": "Սողուն",
