  "Roma": "Հռոմ",
  "Roxa": "Մանուշակագույն",
  "Rússia": "Ռուսաստան",
  "Saara": "Սահարա",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Ընտրվում է գաղտնի կենդանի, և յուրաքանչյուրը գուշակում է այլ կենդանիներ։ Ամեն գուշակություն ցույց է տալիս, թե ինչն է համընկնում գաղտնիի հետ՝ դասը, սնունդը, որտեղ է ապրում և քաշը։ Ով ավելի քիչ փորձով գուշակի, ավելի շատ միավոր կստանա։",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Ընտրվում է գաղտնի դինոզավր, և յուրաքանչյուրը գուշակում է այլ դինոզավրեր։ Ամեն գուշակություն ցույց է տալիս, թե ինչն է համընկնում գաղտնիի հետ՝ ժամանակաշրջանը, սնունդը, խումբը, երկարությունը և որտեղ է գտնվել։ Ով ավելի քիչ փորձով գուշակի, ավելի շատ միավոր կստանա։",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Ընտրվում է գաղտնի քիմիական տարր, և յուրաքանչյուրը գուշակում է այլ տարրեր։ Ամեն գուշակություն ցույց է տալիս, թե ինչն է համընկնում գաղտնիի հետ՝ ընտանիքը, ագրեգատային վիճակը, պարբերությունը, խումբը և ատոմային համարը։ Ով ավելի քիչ փորձով գուշակի, ավելի շատ միավոր կստանա։",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Ընտրվում է Բրազիլիայի գաղտնի նահանգ, և յուրաքանչյուրը գուշակում է այլ նահանգներ։ Ամեն գուշակություն ցույց է տալիս հեռավորությունը և ուղղությունը դեպի գաղտնին, տարածաշրջանը, բնակչությունը, մակերեսը, ծովափը և սահմանն այլ երկրի հետ։ Ով ավելի քիչ փորձով գուշակի, ավելի շատ միավոր կստանա։",
