  "Você aguenta o primeiro ataque dos lobisomens. Ninguém fica sabendo.": "Դու դիմանում ես մարդագայլերի առաջին հարձակմանը։ Ոչ ոք չի իմանում։",
  "Você colheu {n} recursos.": "Հավաքեցիր {n} ռեսուրս։",
  "Você joga por conta própria: vence se a vila tirar você do jogo no julgamento. Levante suspeitas, mas sem exagero.": "Խաղում ես ինքնուրույն. հաղթում ես, եթե գյուղը քեզ խաղից հանի դատավարության ժամանակ։ Կասկածներ արթնացրու, բայց առանց չափազանցության։",
