  "Trazer de um servidor do Discord": "Բերել Discord սերվերից",
  "Link do modelo do servidor": "Սերվերի ձևանմուշի հղումը",
  "Ver o que vem": "Տեսնել՝ ինչ կգա",
  "No Discord, quem cuida do servidor gera o link em Configurações do servidor → Modelo de servidor. Vêm os canais e os cargos (nome e cor), sem as mensagens.": "Discord-ում հղումը ստեղծում է սերվերը կառավարողը՝ Սերվերի կարգավորումներ → Սերվերի ձևանմուշ բաժնում։ Գալիս են ալիքներն ու դերերը (անուն և գույն), առանց հաղորդագրությունների։",
  "Passou do limite do Syden: {n} ficam de fora.": "Syden-ի սահմանից ավելի է՝ {n}-ը դուրս է մնում։",
  "Esse link não é de um modelo de servidor do Discord.": "Այս հղումը Discord սերվերի ձևանմուշ չէ։",
  "Esse modelo não existe no Discord. Peça um link novo a quem cuida do servidor.": "Այս ձևանմուշը Discord-ում չկա։ Նոր հղում խնդրիր սերվերը կառավարողից։",
  "O Discord não respondeu. Tente de novo daqui a pouco.": "Discord-ը չպատասխանեց։ Մի քիչ հետո նորից փորձիր։",
  // O celular como câmera (23/11/2026)
  "Usar o celular como câmera": "Օգտագործել հեռախոսը որպես տեսախցիկ",
  "Aponte a câmera do celular para o código e abra o endereço que aparecer.": "Հեռախոսի տեսախցիկն ուղղիր կոդին և բացիր հայտնված հասցեն։",
  "O celular e o computador precisam estar na mesma rede Wi-Fi.": "Հեռախոսը և համակարգիչը պետք է լինեն նույն Wi-Fi ցանցում։",
  "Não deu para abrir o código agora. Tente de novo.": "Այս պահին չհաջողվեց ցույց տալ կոդը։ Նորից փորձիր։",
  "Ligando o celular ao computador…": "Հեռախոսը միացվում է համակարգչին…",
  "A câmera do celular está na chamada.": "Հեռախոսի տեսախցիկը զանգի մեջ է։",
  "Não deu para ligar o celular ao computador. Os dois precisam estar na mesma rede Wi-Fi.": "Չհաջողվեց հեռախոսը միացնել համակարգչին։ Երկուսն էլ պետք է լինեն նույն Wi-Fi ցանցում։",
  "O celular saiu.": "Հեռախոսն անջատվեց։",
  "Abrindo a câmera…": "Տեսախցիկը բացվում է…",
  "O navegador não deixou abrir a câmera. Permita a câmera para este site e abra o código de novo.": "Դիտարկիչը թույլ չտվեց բացել տեսախցիկը։ Թույլատրիր տեսախցիկն այս կայքի համար և նորից բացիր կոդը։",
  "Este código já foi usado ou venceu. Peça outro no computador.": "Այս կոդն արդեն օգտագործվել է կամ ժամկետն անցել է։ Համակարգչում նորը խնդրիր։",
  "Pronto. Pode fechar esta página.": "Պատրաստ է։ Կարող ես փակել այս էջը։",
  // Banir da comunidade e fixar mensagens (23/11/2026)
  "Mensagens fixadas": "Ամրացված հաղորդագրություններ",
  "Nenhuma mensagem fixada.": "Ամրացված հաղորդագրություն չկա։",
  "Ir até a mensagem": "Անցնել հաղորդագրությանը",
  "Desafixar mensagem": "Ապամրացնել հաղորդագրությունը",
  "Fixar mensagem": "Ամրացնել հաղորդագրությունը",
  "Fixada": "Ամրացված է",
  "Pessoas banidas": "Արգելափակված մարդիկ",
  "Ninguém foi banido desta comunidade.": "Այս համայնքում ոչ ոք արգելափակված չէ։",
  "Por {pessoa}, em {data}": "{pessoa}, {data}",
  "Desbanir {pessoa}": "Հանել արգելափակումը՝ {pessoa}",
  "Banir {pessoa}": "Արգելափակել՝ {pessoa}",
  "Banir da comunidade…": "Արգելափակել համայնքում…",
  "Banir da comunidade": "Արգելափակել համայնքում",
  "Banir": "Արգելափակել",
  "{pessoa} sai da comunidade e das chamadas dela na hora, e só volta se alguém que administra desbanir.": "{pessoa}-ն անմիջապես դուրս է գալիս համայնքից և նրա զանգերից և կարող է վերադառնալ միայն, եթե որևէ ադմինիստրատոր հանի արգելափակումը։",
  "Quem administra esta comunidade baniu a sua conta, e por isso não dá para entrar.": "Այս համայնքի ադմինիստրատորները արգելափակել են քո հաշիվը, ուստի չես կարող մտնել։",
  "Só quem administra a comunidade pode banir alguém.": "Միայն համայնքի ադմինիստրատորները կարող են արգելափակել որևէ մեկին։",
  "Só quem administra a comunidade pode desbanir alguém.": "Միայն համայնքի ադմինիստրատորները կարող են հանել արգելափակումը։",
  "Essa pessoa não está banida.": "Այս մարդը արգելափակված չէ։",
  "Só quem administra a comunidade fixa mensagens.": "Հաղորդագրությունները ամրացնում են միայն համայնքի ադմինիստրատորները։",
  "Só as mensagens do canal podem ser fixadas, não as de um tópico.": "Կարելի է ամրացնել միայն ալիքի հաղորդագրությունները, ոչ թե թեմայինը։",
  "Este canal já tem 50 mensagens fixadas. Desafixe uma antes.": "Այս ալիքում արդեն 50 ամրացված հաղորդագրություն կա։ Նախ ապամրացրու մեկը։",
  // Canal de avisos, editar mensagem, status da sala, registro de moderação e convites com prazo (23/11/2026)
  "(editada)": "(խմբագրված)",
  "Editar mensagem": "Խմբագրել հաղորդագրությունը",
  "Canal de avisos: só quem administra escreve aqui. Para conversar sobre um aviso, abra um tópico nele.": "Հայտարարությունների ալիք․ այստեղ գրում են միայն ադմինիստրատորները։ Որևէ հայտարարության մասին խոսելու համար բացիր ճյուղ դրա վրա։",
  "Canais de avisos": "Հայտարարությունների ալիքներ",
  "Num canal de avisos, só quem administra escreve. A turma lê, reage e conversa nos tópicos de cada aviso.": "Հայտարարությունների ալիքում գրում են միայն ադմինիստրատորները։ Մյուսները կարդում են, արձագանքում և զրուցում յուրաքանչյուր հայտարարության ճյուղում։",
  "{quem} fez de {canal} um canal de avisos": "{quem}-ը {canal}-ը դարձրեց հայտարարությունների ալիք",
  "{quem} tirou o canal de avisos de {canal}": "{quem}-ը {canal}-ից հանեց հայտարարությունների ռեժիմը",
  "Configurar convite": "Կարգավորել հրավերը",
  "Um link a mais, que vence e se gasta como você escolher. O link de sempre continua valendo.": "Եվս մեկ հղում, որի ժամկետը և օգտագործումները դու ես ընտրում։ Սովորական հղումը շարունակում է գործել։",
  "Validade": "Վավերականություն",
  "Limite de usos": "Օգտագործումների սահմանաչափ",
  "30 minutos": "30 րոպե",
  "1 hora": "1 ժամ",
  "6 horas": "6 ժամ",
