  "{usos} de {max} usos": "{usos}՝ {max} օգտագործումից",
  "Gerar link": "Ստեղծել հղում",
  "Seus convites": "Քո հրավերները",
  "Convites": "Հրավերներ",
  "Nenhum convite ativo.": "Ակտիվ հրավեր չկա։",
  "Expira em {data}": "Լրանում է՝ {data}",
  "Não expira": "Չի լրանում",
  "Revogar convite": "Չեղարկել հրավերը",
  "Pode moderar a conversa": "Կարող է մոդերացնել զրույցը",
  "{quem} removeu {alvo} da comunidade": "{quem}-ը {alvo}-ին հեռացրեց համայնքից",
  "{quem} baniu {alvo}": "{quem}-ը արգելափակեց {alvo}-ին",
  "{quem} desbaniu {alvo}": "{quem}-ը հանեց {alvo}-ի արգելափակումը",
  "{quem} advertiu {alvo}": "{quem}-ը զգուշացրեց {alvo}-ին",
  "{quem} silenciou {alvo} por {tempo}": "{quem}-ը {alvo}-ին լռեցրեց՝ {tempo}",
  "{quem} tirou o silêncio de {alvo}": "{quem}-ը հանեց {alvo}-ի լռեցումը",
  "{quem} deu o cargo de administrador a {alvo}": "{quem}-ը {alvo}-ին տվեց ադմինիստրատորի դերը",
  "{quem} tirou o cargo de administrador de {alvo}": "{quem}-ը {alvo}-ից վերցրեց ադմինիստրատորի դերը",
  "{quem} deu o cargo {cargo} a {alvo}": "{quem}-ը {alvo}-ին տվեց {cargo} դերը",
  "{quem} tirou o cargo {cargo} de {alvo}": "{quem}-ը {alvo}-ից վերցրեց {cargo} դերը",
  "{quem} travou o microfone de {alvo}": "{quem}-ը կողպեց {alvo}-ի խոսափողը",
  "{quem} liberou o microfone de {alvo}": "{quem}-ը ազատեց {alvo}-ի խոսափողը",
  "{quem} cortou a transmissão de {alvo}": "{quem}-ը կտրեց {alvo}-ի հեռարձակումը",
  "{quem} apagou uma mensagem de {alvo} em {canal}": "{quem}-ը ջնջեց {alvo}-ի հաղորդագրությունը {canal}-ում",
  "Quem cuida do Syden apagou uma mensagem de {alvo}": "Syden-ին խնամողները ջնջեցին {alvo}-ի հաղորդագրությունը",
  "{quem} fixou uma mensagem de {alvo} em {canal}": "{quem}-ը ամրացրեց {alvo}-ի հաղորդագրությունը {canal}-ում",
  "{quem} desafixou uma mensagem de {alvo} em {canal}": "{quem}-ը ապամրացրեց {alvo}-ի հաղորդագրությունը {canal}-ում",
  "{quem} criou o canal {canal}": "{quem}-ը ստեղծեց {canal} ալիքը",
  "{quem} renomeou o canal {canal} para {nome}": "{quem}-ը {canal} ալիքը վերանվանեց {nome}",
  "{quem} apagou o canal {canal}": "{quem}-ը ջնջեց {canal} ալիքը",
  "{quem} restaurou o canal {canal}": "{quem}-ը վերականգնեց {canal} ալիքը",
  "{quem} pôs o modo lento de {canal} em {tempo}": "{quem}-ը {canal}-ի դանդաղ ռեժիմը դրեց՝ {tempo}",
  "{quem} mudou as regras da moderação automática": "{quem}-ը փոխեց ավտոմատ մոդերացիայի կանոնները",
  "{quem} trocou o código do convite": "{quem}-ը փոխեց հրավերի կոդը",
  "{quem} desligou o modo lento de {canal}": "{quem}-ը անջատեց {canal}-ի դանդաղ ռեժիմը",
  "Definir status da sala": "Սահմանել սենյակի կարգավիճակը",
  "Status da sala": "Սենյակի կարգավիճակ",
  "Ex.: ranqueada, não chamar": "Օր.՝ վարկանիշային, չզանգել",
  "Some quando a sala esvazia": "Անհետանում է, երբ սենյակը դատարկվում է",
  "Tirar o status": "Հանել կարգավիճակը",
  "Neste canal de avisos, só quem administra escreve. Dá para responder num tópico.": "Այս հայտարարությունների ալիքում գրում են միայն ադմինիստրատորները։ Կարող ես պատասխանել ճյուղում։",
  "Só canal de texto vira canal de avisos.": "Միայն տեքստային ալիքը կարող է դառնալ հայտարարությունների ալիք։",
  "Só quem escreveu a mensagem pode editá-la.": "Հաղորդագրությունը կարող է խմբագրել միայն այն գրողը։",
  "Esta mensagem não tem texto para editar.": "Այս հաղորդագրությունը խմբագրելու տեքստ չունի։",
  "A mensagem não pode ficar vazia. Para tirá-la, apague.": "Հաղորդագրությունը չի կարող դատարկ մնալ։ Այն հեռացնելու համար ջնջիր։",
  "Este convite expirou.": "Այս հրավերի ժամկետը լրացել է։",
  "Este convite já foi usado o máximo de vezes.": "Այս հրավերն արդեն օգտագործվել է առավելագույն քանակով։",
  "Escolha uma validade e um limite de usos da lista.": "Ցանկից ընտրիր վավերականություն և օգտագործումների սահմանաչափ։",
  "Você já tem convites demais nesta comunidade. Revogue algum antes de criar outro.": "Այս համայնքում արդեն չափազանց շատ հրավերներ ունես։ Նորը ստեղծելուց առաջ չեղարկիր մեկը։",
  "Convite não encontrado.": "Հրավերը չի գտնվել։",
  "Só quem criou o convite, ou quem administra a comunidade, pode revogá-lo.": "Հրավերը կարող են չեղարկել միայն այն ստեղծողը կամ համայնքի ադմինիստրատորները։",
  "Só quem administra a comunidade vê o registro de moderação.": "Մոդերացիայի գրանցամատյանը տեսնում են միայն համայնքի ադմինիստրատորները։",
  "Só quem está na sala muda o status dela.": "Սենյակի կարգավիճակը կարող են փոխել միայն նրանում գտնվողները։",
  "O status da sala tem no máximo 60 caracteres.": "Սենյակի կարգավիճակը կարող է ունենալ առավելագույնը 60 նիշ։",
  "A sala está vazia: o status só aparece com alguém nela.": "Սենյակը դատարկ է․ կարգավիճակը երևում է միայն, երբ այնտեղ ինչ-որ մեկը կա։",
  "Esta comunidade não permite uma das palavras deste status.": "Այս համայնքը թույլ չի տալիս այս կարգավիճակի բառերից մեկը։",
